from fastapi import APIRouter, Depends
from fastapi.responses import StreamingResponse
from pydantic import BaseModel
import json
import asyncio

from core.dependencies import get_provider_factory
from providers.base import LLMMessage
from providers.factory import ProviderFactory

router = APIRouter(prefix="/api/content", tags=["content"])


class GenerateRequest(BaseModel):
    """İçerik üretim isteği."""
    prompt: str
    content_type: str = "blog_post"
    tone: str = "professional"
    provider: str | None = None  # None = default provider
    stream: bool = True
    temperature: float = 0.7
    max_tokens: int = 4096


async def sse_generator(
    factory: ProviderFactory,
    messages: list[LLMMessage],
    provider_name: str | None,
    **kwargs
):
    """SSE (Server-Sent Events) formatında stream.

    SSE formatı:
    data: {"type": "token", "content": "Merhaba"}
    data: {"type": "token", "content": " dünya"}
    data: {"type": "done", "usage": {...}}

    Neden SSE?
    - WebSocket'ten daha basit (tek yönlü yeterli)
    - HTTP/2 ile multiplexing
    - Otomatik reconnection (EventSource API)
    - Proxy ve CDN uyumlu
    """
    total_content = ""
    try:
        provider = factory.get_provider(
            provider_name or "openai"
        )

        async for token in provider.stream(
            messages, **kwargs
        ):
            total_content += token
            # SSE formatı: "data: ...\n\n"
            event_data = json.dumps({
                "type": "token",
                "content": token
            })
            yield f"data: {event_data}\n\n"

        # Stream tamamlandı - final event gönder
        # Token sayısını hesapla
        input_text = " ".join(m.content for m in messages)
        input_tokens = provider.count_tokens(input_text)
        output_tokens = provider.count_tokens(total_content)
        cost = provider.calculate_cost(
            input_tokens, output_tokens
        )

        done_data = json.dumps({
            "type": "done",
            "usage": {
                "input_tokens": input_tokens,
                "output_tokens": output_tokens,
                "cost_usd": cost,
                "provider": provider.provider_name
            }
        })
        yield f"data: {done_data}\n\n"

    except Exception as e:
        # Hata durumunda error event gönder
        error_data = json.dumps({
            "type": "error",
            "message": str(e)
        })
        yield f"data: {error_data}\n\n"


@router.post("/generate")
async def generate_content(
    request: GenerateRequest,
    factory: ProviderFactory = Depends(get_provider_factory)
):
    """İçerik üret - streaming veya batch."""
    # Mesajları hazırla
    messages = [
        LLMMessage(
            role="system",
            content=(
                f"Sen profesyonel bir içerik yazarısın. "
                f"İçerik türü: {request.content_type}. "
                f"Ton: {request.tone}. "
                f"Türkçe yaz."
            )
        ),
        LLMMessage(role="user", content=request.prompt)
    ]

    if request.stream:
        return StreamingResponse(
            sse_generator(
                factory, messages, request.provider,
                temperature=request.temperature,
                max_tokens=request.max_tokens
            ),
            media_type="text/event-stream",
            headers={
                # CORS ve cache headers
                "Cache-Control": "no-cache",
                "Connection": "keep-alive",
                "X-Accel-Buffering": "no"  # nginx buffering kapalı
            }
        )
    else:
        # Non-streaming response
        response = await factory.generate_with_fallback(
            messages,
            preferred_provider=request.provider,
            temperature=request.temperature,
            max_tokens=request.max_tokens
        )
        return {
            "content": response.content,
            "usage": {
                "input_tokens": response.input_tokens,
                "output_tokens": response.output_tokens,
                "cost_usd": response.cost,
                "provider": response.provider,
                "model": response.model,
                "latency_ms": response.latency_ms
            }
        }


